import re
def valid_ids(trace_id, span_id):
    def valid(value, width):
        return isinstance(value,str) and re.fullmatch(r'[0-9a-f]{'+str(width)+'}',value) is not None and value != '0'*width
    return valid(trace_id,32) and valid(span_id,16)

def elapsed_ms(start_ns, end_ns):
    for value in (start_ns,end_ns):
        if value is not None and (type(value) is not int or not 0 <= value <= 10**18):
            raise ValueError('invalid tick')
    if start_ns is None or end_ns is None:
        return None
    if end_ns < start_ns:
        raise ValueError('backwards interval')
    return (end_ns-start_ns)/1000000

def trace_root(spans):
    if not isinstance(spans,(list,tuple)) or not 1 <= len(spans) <= 64:raise ValueError('span collection')
    parents={}
    for row in spans:
        if not isinstance(row,dict) or 'id' not in row or 'parent' not in row:raise ValueError('shape')
        ident,parent=row['id'],row['parent']
        if not isinstance(ident,str) or not ident.strip() or len(ident)>64:raise ValueError('id')
        if parent is not None and (not isinstance(parent,str) or not parent.strip() or len(parent)>64):raise ValueError('parent')
        if ident in parents:raise ValueError('duplicate')
        parents[ident]=parent
    roots=[ident for ident,parent in parents.items() if parent is None]
    if len(roots)!=1:raise ValueError('one root required')
    for ident in parents:
        seen=set()
        node=ident
        while node is not None:
            if node not in parents or node in seen:raise ValueError('orphan or cycle')
            seen.add(node)
            node=parents[node]
    return roots[0]

def self_time_ns(start,end,children):
    if any(type(v) is not int or not 0<=v<=10**18 for v in (start,end)) or start>end:raise ValueError('parent')
    if not isinstance(children,(list,tuple)) or len(children)>64:raise ValueError('children')
    parts=[]
    for pair in children:
        if not isinstance(pair,(list,tuple)) or len(pair)!=2:raise ValueError('pair')
        a,b=pair
        if type(a) is not int or type(b) is not int or not start<=a<=b<=end:raise ValueError('interval')
        parts.append((a,b))
    covered=0
    cursor=start
    for a,b in sorted(parts):
        covered+=max(0,b-max(a,cursor))
        cursor=max(cursor,b)
    return end-start-covered

def usage_record(input_tokens,output_tokens,cached_input_tokens,source):
    if source not in ('provider_reported','estimated','synthetic_fixture','not_reported','not_applicable'):raise ValueError('source')
    values=(input_tokens,output_tokens,cached_input_tokens)
    if any(v is not None and (type(v) is not int or not 0<=v<=100000000) for v in values):raise ValueError('count')
    if cached_input_tokens is not None and (input_tokens is None or cached_input_tokens>input_tokens):raise ValueError('cache')
    if source in ('not_reported','not_applicable') and any(v is not None for v in values):raise ValueError('invented count')
    return dict(input_tokens=input_tokens,output_tokens=output_tokens,cached_input_tokens=cached_input_tokens,source=source)

def metadata_only(record):
    if not isinstance(record,dict) or len(record)>64:raise ValueError('record')
    output={}
    for key in ('request_id','model_id','model_revision','candidate_count','input_tokens','output_tokens'):
        if key not in record:continue
        value=record[key]
        if not (value is None or (isinstance(value,str) and len(value)<=128) or (type(value) is int and 0<=value<=100000000)):raise ValueError('attribute')
        output[key]=value
    return output

def source_units(spans):
    seen=set()
    output=[]
    for span in spans:
        key=span['key']
        if key not in seen:
            seen.add(key)
            output.append(key)
    return output

def first_difference(baseline,candidate):
    for key in ('scope','queries','candidates','reranked','context','prompt','response'):
        if baseline[key]!=candidate[key]:return key
    return None

import hashlib,json
def manifest_digest(manifest):
    if not isinstance(manifest,dict):raise ValueError('dict required')
    try:
        payload=json.dumps(manifest,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False)
        if len(payload)>20000:raise ValueError('size')
        encoded=payload.encode('utf-8')
    except (TypeError,ValueError,UnicodeError) as error:
        raise ValueError('canonical manifest required') from error
    return hashlib.sha256(encoded).hexdigest()

def append_bounded(records,record,limit):
    if type(limit) is not int or not 0<=limit<=64 or not isinstance(records,(list,tuple)) or len(records)>limit:raise ValueError('capacity')
    output=list(records)
    dropped=len(output)==limit
    if not dropped:output.append(record)
    return output,dropped

from copy import deepcopy
def synthetic_capture(request,spans,enabled):
    if type(enabled) is not bool:raise ValueError('explicit bool required')
    if not enabled:return None
    return deepcopy({'request':request,'spans':[s for s in spans if s['authorized'] is True]})

def attempt_totals(attempts):
    if not isinstance(attempts,(list,tuple)) or len(attempts)>64:raise ValueError('attempts')
    seen=set()
    for row in attempts:
        if not isinstance(row,dict) or not {'attempt_id','input_tokens','output_tokens'}<=row.keys():raise ValueError('shape')
        ident=row['attempt_id']
        if not isinstance(ident,str) or not ident.strip() or len(ident)>64 or ident in seen:raise ValueError('id')
        seen.add(ident)
        for key in ('input_tokens','output_tokens'):
            value=row[key]
            if value is not None and (type(value) is not int or not 0<=value<=100000000):raise ValueError('count')
    output={'attempt_count':len(attempts)}
    for key in ('input_tokens','output_tokens'):
        output[key]=sum(r[key] for r in attempts) if attempts and all(r[key] is not None for r in attempts) else None
    return output

