def validate_messages(messages):
    if not isinstance(messages,(list,tuple)) or len(messages)!=2:raise ValueError('messages')
    output=[]
    for row,role in zip(messages,('system','user')):
        if not isinstance(row,dict) or set(row)!={'role','content'} or row['role']!=role:raise ValueError('role/keys')
        text=row['content']
        if not isinstance(text,str) or not text.strip():raise ValueError('text')
        try:text.encode('utf-8')
        except UnicodeError as error:raise ValueError('UTF-8') from error
        output.append((role,text))
    if sum(len(text) for _,text in output)>20000:raise ValueError('size')
    return tuple(output)

def paired_latency(baseline,candidate):
    for group in (baseline,candidate):
        if not isinstance(group,dict) or len(group)>64:raise ValueError('mapping')
        for key,value in group.items():
            if not isinstance(key,str) or not key.strip() or len(key)>64:raise ValueError('id')
            if value is not None and (type(value) is not int or not 0<=value<=10**18):raise ValueError('duration')
    if set(baseline)!=set(candidate):raise ValueError('population differs')
    rows=[]
    excluded=0
    for key in sorted(baseline):
        b,c=baseline[key],candidate[key]
        if b is None or c is None:excluded+=1;continue
        rows.append(dict(request_id=key,baseline_ms=b/1000000,candidate_ms=c/1000000,delta_ms=(c-b)/1000000))
    return dict(pairs=rows,excluded=excluded)
